def is_valid_brackets(s):
    matching = {')': '(', '}': '{', ']': '['}
    stack = []
    for char in s:
        if char in matching.values():
            stack.append(char)
        elif char in matching:
            if not stack or stack.pop() != matching[char]:
                return False
    # Bug: Forgot to verify all opened brackets were closed!
    return True

