class MessageQueue:
    def __init__(self):
        self.items = []

    def enqueue(self, item):
        self.items.append(item)

    def dequeue(self):
        if not self.items:
            return None
        # Bug: pop() without index removes the newest item (LIFO)!
        return self.items.pop()

