def group_anagrams(words):
    groups = {}
    for word in words:
        counts = [0] * 26
        for char in word:
            counts[ord(char) - ord('a')] += 1
        # Bug: lists cannot be used as dictionary keys!
        key = counts
        if key not in groups:
            groups[key] = []
        groups[key].append(word)
    return list(groups.values())

