def merge_intervals(intervals):
    if not intervals:
        return []
    intervals.sort(key=lambda x: x[0])
    merged = [intervals[0]]
    for current in intervals[1:]:
        prev = merged[-1]
        if current[0] <= prev[1]:
            # Bug: Overwriting end with current[1] can shrink the interval!
            prev[1] = current[1]
        else:
            merged.append(current)
    return merged

