def has_cycle(graph):
    visited = set()

    def dfs(node, parent):
        # Bug: Adding to visited AFTER exploring neighbors causes infinite recursion!
        for neighbor in graph.get(node, []):
            if neighbor == parent:
                continue
            if neighbor in visited:
                return True
            if dfs(neighbor, node):
                return True
        visited.add(node)
        return False

    for n in graph:
        if n not in visited:
            if dfs(n, None):
                return True
    return False

