from collections import deque

def find_order(num_tasks, prerequisites):
    adj = {i: [] for i in range(num_tasks)}
    indegree = [0] * num_tasks
    for dest, src in prerequisites:
        adj[src].append(dest)
        indegree[dest] += 1

    queue = deque([i for i in range(num_tasks) if indegree[i] == 0])
    order = []

    while queue:
        curr = queue.popleft()
        order.append(curr)
        for neighbor in adj[curr]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                queue.append(neighbor)

    # Bug: If a cycle exists, order contains partial tasks instead of empty list!
    return order

