def find_two_unique(nums):
    xor_all = 0
    for n in nums:
        xor_all ^= n

    # Bug: 'x & (x - 1)' clears the lowest bit instead of isolating it!
    diff_bit = xor_all & (xor_all - 1)

    num1, num2 = 0, 0
    for n in nums:
        if n & diff_bit:
            num1 ^= n
        else:
            num2 ^= n
    return sorted([num1, num2])

res = find_two_unique([1, 2, 1, 3, 2, 5])
print(f"Unique numbers: {res}")
